#pragma once
/**
 * @file IonoConstraintRows.hpp
 * @brief The ionosphere constraint rows (W6): the SH-VTEC tie and the external GIM rows.
 *
 * A family file of PASS B's station build: the steps of the family in
 * kStationBuildSteps / kStationCarrySteps (network/assembly/StationBuild.hpp), generated by
 * scripts/nom_pb1b_cut.py from the frozen text of networkPassB_'s produce loop.
 */

#include <cstdint>
#include "network/state/Entities.hpp"   // net::LosTable (the SH deviation carries)
#include "network/driver/RunTypes.hpp"
#include "network/assembly/Contributions.hpp"
#include "common/PppObservation.hpp"
#include "math/TimeUtils.hpp"
#include <Eigen/Dense>
#include <map>
#include <memory>
#include <string>
#include <vector>

namespace GnssProcessor {

// ---- PASS B station steps, declarations (generated by scripts/nom_pb1b_cut.py) ----

struct StationBuild;                       // network/assembly/StationBuild.hpp
struct StationCarryFrame;                  // network/assembly/StationBuild.hpp
enum class StationStep : std::uint8_t;     // network/assembly/StationBuild.hpp
class GnssConfig;
class NetworkEstimator;
class SphericalHarmonicIonosphere;
class GlobalIonosphereMap;
struct GlobalVtecShConfig;

/**
 * @brief The ionosphere constraint (W6): the SH-VTEC tie rows or the external GIM rows.
 *
 * Step `iono_constraint` of kStationBuildSteps (network/assembly/StationBuild.hpp); its kinds:
 * ShIonoTie, GimIono. Records: gim_rows. The frozen text of networkPassB_'s produce loop below
 * its bindings.
 * @param build One station's build: the station and its slot writable, the run read only.
 * @return StationStep::Next.
 */
StationStep networkIonoConstraintRows(StationBuild& build);

/**
 * @brief GIM ionosphere pseudo-observation rows (W6 satellite code-bias
 *        prerequisite), folded into station @p st's own block with the
 *        per-constellation common-mode-free R (decomposition INC-7).
 *        Implemented in @c ApplicationNetworkAssembly.cpp.
 *
 * @param[in,out] A_s,A_r,w,y  The station's design blocks, extended in place.
 * @param[in,out] tags  The station's row tags: one @c GimIono tag per
 *                      appended row, in row order.
 * @return What the builder did (suspect 4): no GIM loaded, the
 *         ionosphere weighting off, no qualifying line of sight, or rows appended.
 *
 * A free function (formerly Application::networkAppendGimIonoRows_), so the station
 * steps in the family files can call it; @p config_ is the run's configuration, @p gim_ Application::gim_.
 *
 * @param config_  The run's configuration; its ionosphere weighting block (enable flag,
 *                 elevation cutoff in degrees, sigma floor and scale, common-mode sigma in m) sets the rows.
 * @param gim_     The loaded global ionosphere map, queried read only; null or not loaded
 *                 returns @c NoGim.
 * @param st       The station whose block receives the rows; its ECEF position and slant-iono
 *                 slots are read.
 * @param sta_obs  The station's modelled observations this epoch (satellite id, elevation in
 *                 degrees, satellite ECEF position); GLONASS entries are skipped.
 * @param h2local  Station state index to A_r column of the station's local block this epoch; a
 *                 slant-iono state absent from it gets no row.
 * @param t        Epoch time at which the map is evaluated.
 */
GimRowsOutcome networkAppendGimIonoRows(const GnssConfig& config_,
                                        const std::unique_ptr<GlobalIonosphereMap>& gim_,
                                        NetStation& st, const std::vector<PppObservation>& sta_obs,
                                        const std::map<int, int>& h2local, const GnssTime& t,
                                        Eigen::MatrixXd& A_s, Eigen::MatrixXd& A_r,
                                        Eigen::VectorXd& w, Eigen::VectorXd& y,
                                        std::vector<RowTag>& tags);

/**
 * @brief Co-estimated SH-VTEC ionosphere pseudo-observation rows: the
 *        joint slant-iono ↔ SH-field constraint, including the T5 deviation
 *        carry treatment (decomposition INC-7).
 *
 * The run-loop state it reads arrives as explicit parameters: @p sh_model /
 * @p sh_model2 (the Iono-2 dual-layer second shell, null on the single-layer
 * path), @p shc,
 * @p sh_dev_on, @p sh_dev_carry (const: the serial pre-pass ages it, and
 * this function only looks entries up).  Implemented in
 * @c ApplicationNetworkAssembly.cpp.
 *
 * @param[in,out] tags  The station's row tags: one @c ShIonoTie tag per
 *                      appended row (its line of sight's satellite), in row order.
 *
 * A free function (formerly Application::networkAppendShIonoRows_), so the station
 * steps in the family files can call it; @p config_ is the run's configuration.
 *
 * @param config_    The run's configuration; its ionosphere weighting block (enable flag,
 *                   elevation cutoff in degrees, sigma floor in m, common-mode sigma in m) sets the
 *                   rows. With the weighting off, nothing is appended.
 * @param st         The station whose block receives the rows; its ECEF position and slant-iono
 *                   slots are read.
 * @param est        The network estimator, used only to look up the shared-border column of each
 *                   SH coefficient.
 * @param sta_obs    The station's modelled observations this epoch (satellite id, elevation in
 *                   degrees, satellite ECEF position); GLONASS entries are skipped.
 * @param h2local    Station state index to A_r column of the station's local block this epoch; a
 *                   slant-iono state absent from it gets no row.
 * @param t          Epoch time; sets the sun-fixed longitude shift when the field is sun-fixed.
 * @param sh_model   The SH field (first shell); null appends nothing.
 * @param sh_model2  Second shell of the dual-layer field; null on the single-layer path.
 * @param shc        The global VTEC SH settings (Earth radius, representation sigma in TECU,
 *                   row decimation, sun-fixed flag).
 * @param sh_dev_on  True when the deviation carry treatment is armed: the predicted deviation
 *                   enters the innovation and its variance replaces the representation variance.
 * @param sh_dev_los The per-line-of-sight SH deviation carries, read only here; a missing entry is
 *                   a cold seed (zero deviation, steady-state variance).
 * @param sta_index  The station's index in the network, the station key into @p sh_dev_los.
 * @param[in,out] A_s Shared-border design block of the station; rows appended in place (SH
 *                   coefficient columns).
 * @param[in,out] A_r Local design block of the station; rows appended in place (slant-iono
 *                   columns).
 * @param[in,out] w  Row weights; rows appended in place, set to one (rows are whitened).
 * @param[in,out] y  Row innovations; rows appended in place, whitened.
 */
void networkAppendShIonoRows(const GnssConfig& config_, NetStation& st, const NetworkEstimator& est,
                             const std::vector<PppObservation>& sta_obs,
                             const std::map<int, int>& h2local, const GnssTime& t,
                             const std::unique_ptr<SphericalHarmonicIonosphere>& sh_model,
                             const std::unique_ptr<SphericalHarmonicIonosphere>& sh_model2,
                             const GlobalVtecShConfig& shc, bool sh_dev_on,
                             const net::LosTable& sh_dev_los, int sta_index,
                             Eigen::MatrixXd& A_s, Eigen::MatrixXd& A_r, Eigen::VectorXd& w,
                             Eigen::VectorXd& y, std::vector<RowTag>& tags);

// ---- End of the PASS B station steps, declarations ----

} // namespace GnssProcessor
